INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_002', 'DH-P-002', 'Russell Set Paradox', 'SET_THEORY', 'SELF_REFERENCE', 'VERIFIED', 'BOOTSTRAP', 'Stratification into tiered type hierarchies resolves unrestricted comprehension.', 'Set of all sets that do not contain themselves creates ungrounded self-reference.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_003', 'DH-P-003', 'Barber Paradox', 'SET_THEORY', 'SELF_REFERENCE', 'FAMILY_VARIANT', 'BOOTSTRAP', 'Recognized as isomorphic natural language variant of Russell Set Paradox.', 'Barber shaves all and only those who do not shave themselves.', 'FAMILY_VARIANT', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_004', 'DH-P-004', 'Liar Paradox', 'SEMANTIC_LOGIC', 'SELF_REFERENCE', 'VERIFIED', 'BOOTSTRAP', 'Requires multi-valued logic or Tarskian meta-language truth hierarchies.', 'Sentence asserting its own falsehood ("This statement is false").', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_005', 'DH-P-005', 'Grelling-Nelson Paradox', 'SEMANTICS', 'SELF_REFERENCE', 'FAMILY_VARIANT', 'BOOTSTRAP', 'Syntactic stratification eliminates reflexive autological assignment.', 'Is "heterological" (a word not describing itself) heterological?', 'FAMILY_VARIANT', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_006', 'DH-P-006', 'Curry Paradox', 'PROOF_THEORY', 'SELF_REFERENCE', 'VERIFIED', 'BOOTSTRAP', 'Solved by substructural linear logic rejecting contraction.', 'Self-referential conditional implies arbitrary falsehood without negation.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_007', 'DH-P-007', 'Berry Paradox', 'KOLMOGOROV_COMPLEXITY', 'DEFINABILITY', 'VERIFIED', 'BOOTSTRAP', 'Formalized by Kolmogorov complexity bounds and halting limits.', 'The smallest positive integer not definable in under eleven words.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_008', 'DH-P-008', 'Richard Paradox', 'DEFINABILITY', 'DEFINABILITY', 'FAMILY_VARIANT', 'BOOTSTRAP', 'Diagonal element requires definition outside the enumerated language tier.', 'Diagonalization over all definable real numbers.', 'FAMILY_VARIANT', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_009', 'DH-P-009', 'Burali-Forti Paradox', 'SET_THEORY', 'CLASS_THEORY', 'VERIFIED', 'BOOTSTRAP', 'The collection of all ordinals forms a proper class, not a set.', 'The ordinal number of all ordinals must be greater than itself.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_010', 'DH-P-010', 'Cantor Paradox', 'SET_THEORY', 'CLASS_THEORY', 'FAMILY_VARIANT', 'BOOTSTRAP', 'Universal set does not exist under standard ZFC foundation.', 'Power set of universal set must have strictly greater cardinality than universal set.', 'FAMILY_VARIANT', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_011', 'DH-P-011', 'Sorites Paradox', 'VAGUENESS', 'VAGUENESS', 'CLAIM_ONLY', 'BOOTSTRAP', 'Solved via fuzzy logic or contextual boundary tolerance intervals.', 'Removing one grain from a heap leaves a heap; by induction one grain is a heap.', 'CLAIM_ONLY', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_012', 'DH-P-012', 'Ship of Theseus', 'ONTOLOGY', 'IDENTITY', 'CLAIM_ONLY', 'BOOTSTRAP', 'Requires 4D spatio-temporal perdurantism or functional graph equivalence.', 'Gradual replacement of every part raises persistent identity ambiguity.', 'CLAIM_ONLY', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_013', 'DH-P-013', 'Grandfather Paradox', 'TEMPORAL_CAUSALITY', 'TEMPORAL', 'PARTIAL', 'BOOTSTRAP', 'Novikov self-consistency conjecture or closed timelike curve decoherence.', 'Time traveler prevents own lineage, invalidating the travel premise.', 'PARTIAL', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_014', 'DH-P-014', 'Bootstrap Paradox', 'TEMPORAL_CAUSALITY', 'TEMPORAL', 'PARTIAL', 'BOOTSTRAP', 'Ontological loop resolved via topological path-integral boundary conditions.', 'An object or information is sent back in time, creating uncaused existence.', 'PARTIAL', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_015', 'DH-P-015', 'Raven Paradox (Hempel)', 'EPISTEMOLOGY', 'CONFIRMATION', 'VERIFIED', 'BOOTSTRAP', 'Bayesian confirmation theory assigns infinitesimal but non-zero probability.', 'Observing a green apple confirms "All ravens are black" via contrapositive.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_016', 'DH-P-016', 'Goodman New Riddle of Induction (Grue)', 'EPISTEMOLOGY', 'CONFIRMATION', 'CLAIM_ONLY', 'BOOTSTRAP', 'Requires entrenchment criteria and projective syntax constraints.', 'Predicate "grue" (green before t, blue after) equally supported by evidence.', 'CLAIM_ONLY', 1758912805501) ON CONFLICT (id) DO NOTHING;
