INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_018', 'DH-P-018', 'Prisoner Dilemma', 'GAME_THEORY', 'GAME_THEORY', 'VERIFIED', 'BOOTSTRAP', 'Repeated games with tit-for-tat or contractual escrow enforce cooperation.', 'Dominant individual strategy leads to suboptimal collective outcome.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_019', 'DH-P-019', 'Simpson Paradox', 'STATISTICS', 'CAUSAL_INFERENCE', 'VERIFIED', 'BOOTSTRAP', 'Causal DAG modeling (Pearl do-calculus) eliminates confounding bias.', 'Trend appears in groups but reverses when groups are aggregated.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_020', 'DH-P-020', 'Monty Hall Problem', 'PROBABILITY', 'BAYESIAN_UPDATE', 'VERIFIED', 'BOOTSTRAP', 'Bayesian conditioning under host knowledge constraint proves 2/3 win rate.', 'Switching doors doubles win probability from 1/3 to 2/3.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_021', 'DH-P-021', 'Birthday Paradox', 'COMBINATORICS', 'COMBINATORICS', 'VERIFIED', 'BOOTSTRAP', 'Combinatorial pair selection product (1 - prod((365-i)/365)) proves 50.7%.', 'In 23 people, >50% chance of a shared birthday.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_022', 'DH-P-022', 'Banach-Tarski Paradox', 'MEASURE_THEORY', 'MEASURE_THEORY', 'VERIFIED', 'BOOTSTRAP', 'Depends strictly on the Axiom of Choice acting on non-Lebesgue measurable sets.', 'A solid ball can be decomposed into 5 non-measurable sets and reassembled into two.', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
INSERT INTO paradoxes (id, code, name, domain, category, classification, scope, formal_invariant, z3_smt_assertion, verification_status, created_at) VALUES ('px_023', 'DH-P-023', 'Gabriel Horn (Torricelli Trumpet)', 'CALCULUS', 'CALCULUS_LIMITS', 'VERIFIED', 'BOOTSTRAP', 'Integrals for volume and surface area diverge differently across limits.', 'Surface of revolution has infinite surface area but finite volume (pi).', 'VERIFIED', 1758912805501) ON CONFLICT (id) DO NOTHING;
